-- pg/001_init.sql — Clinic Portal schema for PostgreSQL (Neon).
-- Consolidated FINAL state of the previous SQLite migrations 001–005:
-- the SQLite-only procedures (003 backfill, 004 table rebuild adding the
-- 'in_progress' appointment status) are folded into the base DDL because a
-- fresh PostgreSQL schema can be created correctly in one step. Data from an
-- existing SQLite installation is transferred by scripts/import-sqlite.js.
--
-- Type mapping decisions (documented):
--   INTEGER PRIMARY KEY AUTOINCREMENT -> INTEGER GENERATED BY DEFAULT AS IDENTITY
--       (BY DEFAULT allows the import script to insert explicit ids)
--   ISO-8601 TEXT timestamps          -> TIMESTAMPTZ (driver returns the same
--       "YYYY-MM-DDTHH:mm:ss.sssZ" strings as before via a type parser)
--   'YYYY-MM-DD' TEXT dates           -> DATE (returned as the same string)
--   0/1 integer flags                 -> SMALLINT 0/1 (keeps every existing
--       validation/serialization path unchanged)
--   JSON-in-TEXT (working_hours, audit details) -> TEXT (app parses/serializes)
--   UNIQUE COLLATE NOCASE (emails)    -> functional unique index on lower(email)

CREATE TABLE clinics (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name TEXT NOT NULL,
  slug TEXT NOT NULL UNIQUE,
  email TEXT,
  phone TEXT,
  address TEXT,
  timezone TEXT NOT NULL DEFAULT 'UTC',
  slot_minutes INTEGER NOT NULL DEFAULT 30,
  working_hours TEXT NOT NULL DEFAULT '{}',   -- JSON: {"0":{"start":"08:00","end":"17:00"}, ...} 0=Sunday
  currency TEXT NOT NULL DEFAULT 'ILS',
  status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active','suspended')),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE branches (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  clinic_id INTEGER NOT NULL REFERENCES clinics(id) ON DELETE CASCADE,
  name TEXT NOT NULL,
  address TEXT,
  is_active SMALLINT NOT NULL DEFAULT 1,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX idx_branches_clinic ON branches(clinic_id);

CREATE TABLE users (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  clinic_id INTEGER REFERENCES clinics(id) ON DELETE CASCADE,  -- NULL for platform admins
  email TEXT NOT NULL,
  password_hash TEXT NOT NULL,
  full_name TEXT NOT NULL,
  role TEXT NOT NULL CHECK (role IN ('platform_admin','owner','receptionist','doctor','accountant')),
  phone TEXT,
  is_active SMALLINT NOT NULL DEFAULT 1,
  token_version INTEGER NOT NULL DEFAULT 1,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
-- Case-insensitive uniqueness, replacing SQLite's UNIQUE COLLATE NOCASE.
CREATE UNIQUE INDEX uq_users_email_lower ON users (lower(email));
CREATE INDEX idx_users_clinic ON users(clinic_id);

CREATE TABLE doctors (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  clinic_id INTEGER NOT NULL REFERENCES clinics(id) ON DELETE CASCADE,
  user_id INTEGER REFERENCES users(id) ON DELETE SET NULL,  -- set when the doctor has a login
  name TEXT NOT NULL,
  specialty TEXT,
  color TEXT NOT NULL DEFAULT '#0d8f7e',
  is_active SMALLINT NOT NULL DEFAULT 1,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX idx_doctors_clinic ON doctors(clinic_id);

CREATE TABLE patients (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  clinic_id INTEGER NOT NULL REFERENCES clinics(id) ON DELETE CASCADE,
  mrn TEXT NOT NULL,                          -- patient number, unique per clinic
  first_name TEXT NOT NULL,
  last_name TEXT NOT NULL,
  first_name_norm TEXT,                       -- normalized search derivatives
  last_name_norm TEXT,
  dob DATE,
  gender TEXT CHECK (gender IN ('male','female','other') OR gender IS NULL),
  phone TEXT,
  email TEXT,
  address TEXT,
  allergies TEXT,
  medical_info TEXT,
  is_active SMALLINT NOT NULL DEFAULT 1,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (clinic_id, mrn)
);
CREATE INDEX idx_patients_clinic ON patients(clinic_id);
CREATE INDEX idx_patients_name ON patients(clinic_id, last_name, first_name);
CREATE INDEX idx_patients_norm ON patients(clinic_id, first_name_norm, last_name_norm);

CREATE TABLE services (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  clinic_id INTEGER NOT NULL REFERENCES clinics(id) ON DELETE CASCADE,
  name TEXT NOT NULL,
  description TEXT,
  duration_min INTEGER NOT NULL DEFAULT 30,
  price_cents INTEGER NOT NULL DEFAULT 0,
  is_active SMALLINT NOT NULL DEFAULT 1,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX idx_services_clinic ON services(clinic_id);

CREATE TABLE appointments (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  clinic_id INTEGER NOT NULL REFERENCES clinics(id) ON DELETE CASCADE,
  branch_id INTEGER REFERENCES branches(id) ON DELETE SET NULL,
  patient_id INTEGER NOT NULL REFERENCES patients(id),
  doctor_id INTEGER NOT NULL REFERENCES doctors(id),
  service_id INTEGER REFERENCES services(id),
  status TEXT NOT NULL DEFAULT 'scheduled'
    CHECK (status IN ('scheduled','confirmed','checked_in','in_progress','completed','cancelled','no_show')),
  start_at TIMESTAMPTZ NOT NULL,              -- UTC instant
  duration_min INTEGER NOT NULL CHECK (duration_min > 0 AND duration_min <= 480),
  notes TEXT,
  created_by INTEGER REFERENCES users(id),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX idx_appt_clinic_time ON appointments(clinic_id, start_at);
CREATE INDEX idx_appt_doctor_time ON appointments(doctor_id, start_at);
CREATE INDEX idx_appt_patient ON appointments(patient_id);

CREATE TABLE medical_records (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  clinic_id INTEGER NOT NULL REFERENCES clinics(id) ON DELETE CASCADE,
  patient_id INTEGER NOT NULL REFERENCES patients(id),
  appointment_id INTEGER REFERENCES appointments(id) ON DELETE SET NULL,
  doctor_id INTEGER NOT NULL REFERENCES doctors(id),
  visit_date DATE NOT NULL,                   -- clinic local date
  symptoms TEXT,
  examination TEXT,
  diagnosis TEXT,
  treatment TEXT,
  follow_up TEXT,
  status TEXT NOT NULL DEFAULT 'approved' CHECK (status IN ('draft','approved')),
  created_by INTEGER REFERENCES users(id),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX idx_records_patient ON medical_records(clinic_id, patient_id);
CREATE INDEX idx_records_doctor ON medical_records(doctor_id);

CREATE TABLE prescriptions (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  clinic_id INTEGER NOT NULL REFERENCES clinics(id) ON DELETE CASCADE,
  record_id INTEGER NOT NULL REFERENCES medical_records(id) ON DELETE CASCADE,
  patient_id INTEGER NOT NULL REFERENCES patients(id),
  medication TEXT NOT NULL,
  dosage TEXT,
  frequency TEXT,
  duration TEXT,
  notes TEXT,
  prescribed_by INTEGER REFERENCES users(id),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX idx_rx_record ON prescriptions(record_id);
CREATE INDEX idx_rx_patient ON prescriptions(clinic_id, patient_id);

CREATE TABLE invoices (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  clinic_id INTEGER NOT NULL REFERENCES clinics(id) ON DELETE CASCADE,
  invoice_no TEXT NOT NULL,
  patient_id INTEGER NOT NULL REFERENCES patients(id),
  appointment_id INTEGER REFERENCES appointments(id) ON DELETE SET NULL,
  issue_date DATE NOT NULL,
  due_date DATE,
  notes TEXT,
  subtotal_cents INTEGER NOT NULL DEFAULT 0,
  total_cents INTEGER NOT NULL DEFAULT 0,
  currency TEXT,                              -- snapshot (historical amounts keep their currency)
  status TEXT NOT NULL DEFAULT 'unpaid' CHECK (status IN ('unpaid','partial','paid')),
  created_by INTEGER REFERENCES users(id),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (clinic_id, invoice_no)
);
CREATE INDEX idx_invoices_clinic ON invoices(clinic_id, issue_date);
CREATE INDEX idx_invoices_patient ON invoices(patient_id);

CREATE TABLE invoice_items (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  invoice_id INTEGER NOT NULL REFERENCES invoices(id) ON DELETE CASCADE,
  clinic_id INTEGER NOT NULL REFERENCES clinics(id) ON DELETE CASCADE,
  service_id INTEGER REFERENCES services(id) ON DELETE SET NULL,
  description TEXT NOT NULL,
  quantity INTEGER NOT NULL DEFAULT 1 CHECK (quantity > 0),
  unit_price_cents INTEGER NOT NULL DEFAULT 0,
  amount_cents INTEGER NOT NULL DEFAULT 0
);
CREATE INDEX idx_items_invoice ON invoice_items(invoice_id);

CREATE TABLE payments (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  invoice_id INTEGER NOT NULL REFERENCES invoices(id) ON DELETE CASCADE,
  clinic_id INTEGER NOT NULL REFERENCES clinics(id) ON DELETE CASCADE,
  amount_cents INTEGER NOT NULL CHECK (amount_cents > 0),
  method TEXT NOT NULL DEFAULT 'cash' CHECK (method IN ('cash','card','bank_transfer','insurance','other')),
  reference TEXT,
  paid_at TIMESTAMPTZ NOT NULL,
  received_by INTEGER REFERENCES users(id),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX idx_payments_invoice ON payments(invoice_id);
CREATE INDEX idx_payments_clinic ON payments(clinic_id, paid_at);

CREATE TABLE audit_logs (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  clinic_id INTEGER REFERENCES clinics(id) ON DELETE CASCADE,
  user_id INTEGER REFERENCES users(id) ON DELETE SET NULL,
  action TEXT NOT NULL,
  entity TEXT NOT NULL,
  entity_id INTEGER,
  details TEXT,                               -- JSON
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX idx_audit_clinic ON audit_logs(clinic_id, id);

CREATE TABLE activity (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  clinic_id INTEGER NOT NULL REFERENCES clinics(id) ON DELETE CASCADE,
  user_id INTEGER REFERENCES users(id) ON DELETE SET NULL,
  kind TEXT NOT NULL DEFAULT 'info',
  message TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX idx_activity_clinic ON activity(clinic_id, id);

CREATE TABLE doctor_unavailability (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  clinic_id INTEGER NOT NULL REFERENCES clinics(id) ON DELETE CASCADE,
  doctor_id INTEGER NOT NULL REFERENCES doctors(id) ON DELETE CASCADE,
  start_at TIMESTAMPTZ NOT NULL,
  end_at TIMESTAMPTZ NOT NULL,                -- exclusive
  reason TEXT,
  created_by INTEGER REFERENCES users(id),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX idx_unavail_doctor ON doctor_unavailability(doctor_id, start_at);
CREATE INDEX idx_unavail_clinic ON doctor_unavailability(clinic_id, start_at);

CREATE TABLE attachments (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  clinic_id INTEGER NOT NULL REFERENCES clinics(id) ON DELETE CASCADE,
  entity_type TEXT NOT NULL CHECK (entity_type IN ('medical_record')),
  entity_id INTEGER NOT NULL,
  original_name TEXT NOT NULL,
  stored_name TEXT NOT NULL UNIQUE,           -- generated UUID filename; files live under data/uploads
  mime_type TEXT NOT NULL,
  size_bytes INTEGER NOT NULL,
  sha256 TEXT,
  uploaded_by INTEGER REFERENCES users(id),
  deleted_at TIMESTAMPTZ,                     -- soft delete preserves record history
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX idx_attach_entity ON attachments(clinic_id, entity_type, entity_id);

-- ---------------- dental chart (odontogram) ----------------

CREATE TABLE dental_charts (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  clinic_id INTEGER NOT NULL REFERENCES clinics(id) ON DELETE CASCADE,
  patient_id INTEGER NOT NULL REFERENCES patients(id) ON DELETE CASCADE,
  dentition TEXT NOT NULL DEFAULT 'permanent' CHECK (dentition IN ('permanent','primary','mixed')),
  dentition_suggested TEXT CHECK (dentition_suggested IN ('permanent','primary','mixed') OR dentition_suggested IS NULL),
  created_by INTEGER REFERENCES users(id),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (clinic_id, patient_id)
);

CREATE TABLE dental_findings (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  clinic_id INTEGER NOT NULL REFERENCES clinics(id) ON DELETE CASCADE,
  patient_id INTEGER NOT NULL REFERENCES patients(id) ON DELETE CASCADE,
  chart_id INTEGER NOT NULL REFERENCES dental_charts(id) ON DELETE CASCADE,
  tooth_number INTEGER NOT NULL CHECK (
    (tooth_number / 10 BETWEEN 1 AND 4 AND tooth_number % 10 BETWEEN 1 AND 8)
    OR (tooth_number / 10 BETWEEN 5 AND 8 AND tooth_number % 10 BETWEEN 1 AND 5)
  ),
  dentition TEXT NOT NULL CHECK (dentition IN ('permanent','primary')),
  condition TEXT NOT NULL CHECK (condition IN
    ('healthy','caries','filled','crown','missing','extracted','root_canal',
     'fractured','implant','bridge_pontic','bridge_abutment','impacted','other')),
  surfaces TEXT NOT NULL DEFAULT '',
  status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active','resolved')),
  note TEXT,
  appointment_id INTEGER REFERENCES appointments(id) ON DELETE SET NULL,
  record_id INTEGER REFERENCES medical_records(id) ON DELETE SET NULL,
  created_by INTEGER REFERENCES users(id),
  updated_by INTEGER REFERENCES users(id),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX idx_dental_findings_patient ON dental_findings(clinic_id, patient_id, tooth_number);
CREATE UNIQUE INDEX uq_dental_findings_active
  ON dental_findings(clinic_id, patient_id, tooth_number, condition, surfaces)
  WHERE status = 'active';

CREATE TABLE dental_treatments (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  clinic_id INTEGER NOT NULL REFERENCES clinics(id) ON DELETE CASCADE,
  patient_id INTEGER NOT NULL REFERENCES patients(id) ON DELETE CASCADE,
  chart_id INTEGER NOT NULL REFERENCES dental_charts(id) ON DELETE CASCADE,
  tooth_number INTEGER NOT NULL CHECK (
    (tooth_number / 10 BETWEEN 1 AND 4 AND tooth_number % 10 BETWEEN 1 AND 8)
    OR (tooth_number / 10 BETWEEN 5 AND 8 AND tooth_number % 10 BETWEEN 1 AND 5)
  ),
  dentition TEXT NOT NULL CHECK (dentition IN ('permanent','primary')),
  procedure TEXT NOT NULL CHECK (procedure IN
    ('filling','crown','extraction','root_canal','implant','bridge','cleaning','fluoride','other')),
  surfaces TEXT NOT NULL DEFAULT '',
  note TEXT,
  status TEXT NOT NULL DEFAULT 'planned' CHECK (status IN ('planned','completed','cancelled')),
  appointment_id INTEGER REFERENCES appointments(id) ON DELETE SET NULL,
  record_id INTEGER REFERENCES medical_records(id) ON DELETE SET NULL,
  planned_by INTEGER REFERENCES users(id),
  planned_at TIMESTAMPTZ NOT NULL,
  completion_note TEXT,
  completed_by INTEGER REFERENCES users(id),
  completed_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX idx_dental_treatments_patient ON dental_treatments(clinic_id, patient_id, status);

CREATE TABLE dental_history (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  clinic_id INTEGER NOT NULL REFERENCES clinics(id) ON DELETE CASCADE,
  patient_id INTEGER NOT NULL REFERENCES patients(id) ON DELETE CASCADE,
  tooth_number INTEGER,
  dentition TEXT,
  event_type TEXT NOT NULL CHECK (event_type IN
    ('finding_created','finding_updated','finding_resolved',
     'treatment_planned','treatment_completed','treatment_cancelled','treatment_reopened',
     'chart_config','correction')),
  entity TEXT NOT NULL CHECK (entity IN ('finding','treatment','chart')),
  entity_id INTEGER NOT NULL,
  old_value TEXT,                             -- JSON snapshot before the change
  new_value TEXT,                             -- JSON snapshot after the change
  reason TEXT,
  note TEXT,
  appointment_id INTEGER REFERENCES appointments(id) ON DELETE SET NULL,
  record_id INTEGER REFERENCES medical_records(id) ON DELETE SET NULL,
  user_id INTEGER REFERENCES users(id),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX idx_dental_history_patient ON dental_history(clinic_id, patient_id, created_at, id);
CREATE INDEX idx_dental_history_tooth ON dental_history(clinic_id, patient_id, tooth_number);
